using System.Security.Claims;
using Microsoft.IdentityModel.JsonWebTokens;
using Microsoft.IdentityModel.Tokens;

public sealed class TokenIssuer(SigningCredentials signing)
{
    public string Issue(Customer c) => new JsonWebTokenHandler().CreateToken(
        new SecurityTokenDescriptor
        {
            Subject = new ClaimsIdentity(
            [
                new Claim("sub", c.Id.ToString()),
                new Claim("email", c.Email),
                new Claim("phone", c.Phone),
                new Claim("date_of_birth", c.DateOfBirth.ToString("O")),
                new Claim("credit_limit", c.CreditLimit.ToString()),
            ]),
            Expires = DateTime.UtcNow.AddMinutes(15),
            SigningCredentials = signing, // signed, not encrypted
        });
}

using System.Security.Claims;
using Microsoft.IdentityModel.JsonWebTokens;
using Microsoft.IdentityModel.Tokens;

public sealed class TokenIssuer(SigningCredentials signing)
{
    // Who, for which API, until when. The API looks up the rest by sub.
    public string Issue(Customer c) => new JsonWebTokenHandler().CreateToken(
        new SecurityTokenDescriptor
        {
            Subject = new ClaimsIdentity([new Claim("sub", c.Id.ToString())]),
            Issuer = "https://auth.example.com",
            Audience = "orders-api",
            Expires = DateTime.UtcNow.AddMinutes(15),
            SigningCredentials = signing,
        });
}

